422: function run_command(display_cmd, cmd, msg = "", dry = false, show = false) {
423:     var bot = getUrlParameter('bot_id');
424:     $("#command-show").show().html("intelmqctl run {0} {1} {2}".format(bot, display_cmd, msg ? "'" + msg.replace("'", "'\\''") + "'" : ""));//XX dry are not syntax-correct
425:     $("#run-log").val("loading...");
426:     $('#inspect-panel-title').addClass('waiting');
427:     let call = $.ajax({
428:         method: "post",
429:         data: {"msg": msg},
430:         url: MANAGEMENT_SCRIPT + '?scope=run&bot={0}&cmd={1}&dry={2}&show={3}'.format(bot, cmd, dry, show),
431:     }).done(function (data) {
432:         // Parses the received data to message part and to log-only part
433:         let logs = [];
434:         let msg = [];
435:         let logging = logs;
436:         for (let line of data.split("\n")) {
437:             if (logging === logs) {
438:                 if (line === "{") {
439:                     logging = msg;
440:                 }
441:             } else {
442:                 if (line === "}") {
443:                     msg.push(line);
444:                     logging = logs;
445:                     continue;
446:                 }
447:             }
448: 
449:             logging.push(line); //write either to logs or msgs
450:         }
451:         if (msg.length) { // we won't rewrite an old message if nothing came
452:             $("#message-playground").attr("rows", msg.length).val(msg.join("\n"));
453:         }
454:         $("#run-log").attr("rows", logs.length).val(logs.join("\n"));
455:     }).fail(ajax_fail_callback('Error getting message'))
456:             .always(() => {
457:                 $('#inspect-panel-title').removeClass('waiting');
458:                 $("#run-log").data("call", null);
459:             });
460: 
461:     // informate user if there is a lag
462:     $("#run-log").data("call", call);
463:     setTimeout(() => {
464:         if ($("#run-log").data("call") === call) {
465:             $("#run-log").val("loading... or timeouting...");
466:         }
467:     }, 3000);
468: }
