488: function getUrlParameter(sParam) {
489:     var sPageURL = decodeURIComponent(window.location.search.substring(1)),
490:             sURLVariables = sPageURL.split('&'),
491:             sParameterName,
492:             i;
493: 
494:     for (i = 0; i < sURLVariables.length; i++) {
495:         sParameterName = sURLVariables[i].split('=');
496: 
497:         if (sParameterName[0] === sParam) {
498:             return sParameterName[1] === undefined ? true : sParameterName[1];
499:         }
500:     }
501: }",
